//S14: CSRF 保護 (Origin/Referer 検証) — 生成時 標準装備テンプレート
// Next.js App Router の Server Actions は Origin を自動検証するが、独自の Route Handler
// (app/api/**/route.ts) の POST/PUT/PATCH/DELETE は自前で同一オリジン検証を行う必要がある。
// クッキー認証のアプリでは、外部サイトからの強制リクエスト (CSRF) を Origin 不一致で弾く。
//
// 使い方 (route handler 冒頭):
//   export async function POST(req: Request) {
//     const csrf = assertSameOrigin(req);
//     if (!csrf.ok) return new Response('forbidden', { status: 403 });
//     ...
//   }

export interface CsrfResult {
  ok: boolean;
  reason?: string;
}

/** 環境変数 (本番URL) を許可オリジンに加える。複数は ALLOWED_ORIGINS をカンマ区切りで。 */
function allowedOrigins(): string[] {
  const list = new Set<string>();
  for (const v of [process.env.NEXTAUTH_URL, process.env.NEXT_PUBLIC_APP_URL, process.env.APP_URL]) {
    if (v) try { list.add(new URL(v).origin); } catch { /* ignore */ }
  }
  for (const v of (process.env.ALLOWED_ORIGINS || '').split(',')) {
    const t = v.trim();
    if (t) try { list.add(new URL(t).origin); } catch { /* ignore */ }
  }
  return [...list];
}

/**
 * リクエストの Origin (なければ Referer) が自分自身かを検証する。
 * 同一オリジン or Host と一致 or 明示許可リストに含まれれば ok。
 */
export function assertSameOrigin(req: Request): CsrfResult {
  const origin = req.headers.get('origin') || '';
  const referer = req.headers.get('referer') || '';
  const host = req.headers.get('host') || '';
  const candidate = origin || (referer ? safeOrigin(referer) : '');

  // Origin/Referer が無いブラウザ以外 (curl 等) は、ブラウザ由来の CSRF ではないため通す。
  if (!candidate) return { ok: true };

  const allow = allowedOrigins();
  if (allow.includes(candidate)) return { ok: true };

  // host ヘッダ一致 (プロキシ背後でも自オリジン判定できる最終フォールバック)
  if (host && (candidate === `https://${host}` || candidate === `http://${host}`)) {
    return { ok: true };
  }
  return { ok: false, reason: `cross-origin request blocked: ${candidate}` };
}

function safeOrigin(url: string): string {
  try { return new URL(url).origin; } catch { return ''; }
}
